/// <summary>
/// Scoped service that holds the current low-stock alert count and
/// notifies all subscribers when the count changes.
/// Scoped lifetime ensures each Blazor Server circuit (user session)
/// gets its own independent instance.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    public void UpdateCount(int count)
    {
        LowStockCount = count;
        OnChange?.Invoke();
    }
}

