@page "/dashboard"
@using sv_1708bc9ae6df4abc8a5ee6b6508f3c57.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IAsyncDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4 mb-3">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@(CurrentWarehouse?.Name ?? "None selected")</p>
                <p class="text-muted">ID: @(CurrentWarehouse?.Id ?? "—")</p>
            </div>
        </div>
    </div>
    <div class="col-md-4 mb-3">
        <div class="card border-danger">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(AlertService.LowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.LowStockCount
                </p>
                <p class="text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4 mb-3">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="text-success fw-bold">● Active</span>
                    }
                    else
                    {
                        <span class="text-secondary">● Stopped</span>
                    }
                </p>
                <p class="text-muted">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? CurrentWarehouse { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private Action? _handler;
    private string? _lastWarehouseId;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        if (CurrentWarehouse is null)
            return;

        // Only restart polling when the warehouse actually changes.
        if (_lastWarehouseId == CurrentWarehouse.Id)
            return;

        _lastWarehouseId = CurrentWarehouse.Id;
        await StopPollingAsync();
        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _isPolling = true;

        // Fetch immediately so the UI isn't stale.
        var count = await AlertService.GetLowStockCountAsync(CurrentWarehouse!.Id);
        AlertService.UpdateCount(count);

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                var count = await AlertService.GetLowStockCountAsync(CurrentWarehouse!.Id);
                AlertService.UpdateCount(count);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when navigating away or switching warehouses.
        }
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _isPolling = false;
    }

    public async ValueTask DisposeAsync()
    {
        AlertService.OnChange -= _handler;
        await StopPollingAsync();
    }
}

