 using sv_1708bc9ae6df4abc8a5ee6b6508f3c57.Components;
 using sv_1708bc9ae6df4abc8a5ee6b6508f3c57.Services;

 var builder = WebApplication.CreateBuilder(args);

 // Add services to the container.
 builder.Services.AddRazorComponents()
     .AddInteractiveServerComponents();

 // CascadingValueSource crosses render-mode boundaries, so the static
 // layout's interactive WarehouseSelector and every interactive page
 // all see the same warehouse selection.  Scoped = one per circuit.
 builder.Services.AddCascadingValue(sp =>
 {
     var initial = new WarehouseInfo { Id = "WH1", Name = "Warehouse A" };
     return new CascadingValueSource<WarehouseInfo>(initial, isFixed: false);
 });

 // Scoped service ensures each Blazor Server circuit (user session)
 // has its own independent alert count — no cross-user leakage.
 builder.Services.AddScoped<InventoryAlertService>();

 var app = builder.Build();

 // Configure the HTTP request pipeline.
 if (!app.Environment.IsDevelopment())
 {
     app.UseExceptionHandler("/Error", createScopeForErrors: true);
 }
 app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
 app.UseAntiforgery();

 app.MapStaticAssets();
 app.MapRazorComponents<App>()
     .AddInteractiveServerRenderMode();

 app.Run();
